// Without reversibility: tightly coupled to Stripe
async function chargeCustomer(userId, amount) {
  const customer = await stripe.customers.retrieve(userId);
  const paymentIntent = await stripe.paymentIntents.create({
    amount,
    customer: customer.id,
  });
  return paymentIntent;
}

// With reversibility: abstracted behind an interface
interface PaymentProvider {
  createPaymentIntent(userId: string, amount: number): Promise<PaymentIntent>;
  refund(paymentId: string, amount: number): Promise<Refund>;
}

class StripeProvider implements PaymentProvider {
  async createPaymentIntent(userId, amount) {
    // Stripe-specific implementation
  }
}

class PayPalProvider implements PaymentProvider {
  async createPaymentIntent(userId, amount) {
    // PayPal-specific implementation
  }
}

// Application code depends on the interface, not the provider
async function chargeCustomer(
  userId: string,
  amount: number,
  provider: PaymentProvider
) {
  return provider.createPaymentIntent(userId, amount);
}

